import random
def experiment(inputs):
    iterations = inputs.get('iterations', 100)
    max_depth = inputs.get('depth', 5)
    branching_history = []
    def generate_task_tree(depth):
        if depth >= max_depth:
            return 1
        # Simulate agent-like task splitting with probabilistic branching
        if random.random() < 0.6:
            branches = random.randint(1, 3)
            total = branches
            for _ in range(branches):
                total += generate_task_tree(depth + 1)
            return total
        return 1
    for _ in range(iterations):
        branching_history.append(generate_task_tree(0))
    return {'measurements': {'branching_factor': branching_history}}

